import time, redis
HOST="127.0.0.1"
src_base=redis.Redis(host=HOST,port=6379)
dst_base=redis.Redis(host=HOST,port=6380)

def dbs(r):
    ks=r.info("keyspace") or {}
    return sorted(int(k[2:]) for k in ks if k.startswith("db") and (ks[k] or {}).get("keys",0)>0)

assert dbs(src_base)==dbs(dst_base), (dbs(src_base),dbs(dst_base))

mismatches=[]
for db in dbs(src_base):
    s=redis.Redis(host=HOST,port=6379,db=db)
    d=redis.Redis(host=HOST,port=6380,db=db)
    sk=set(s.scan_iter(count=1000)); dk=set(d.scan_iter(count=1000))
    if sk!=dk:
        mismatches.append((db,"keyset",len(sk),len(dk)))
    for k in sk:
        st=s.type(k); dt=d.type(k)
        if st!=dt:
            mismatches.append((db,k,"type",st,dt)); continue
        if st=="string":
            if s.get(k)!=d.get(k): mismatches.append((db,k,"value"))
        elif st=="list":
            if s.lrange(k,0,-1)!=d.lrange(k,0,-1): mismatches.append((db,k,"list"))
        elif st=="set":
            if s.smembers(k)!=d.smembers(k): mismatches.append((db,k,"set"))
        elif st=="zset":
            if s.zrange(k,0,-1,withscores=True)!=d.zrange(k,0,-1,withscores=True): mismatches.append((db,k,"zset"))
        elif st=="hash":
            if s.hgetall(k)!=d.hgetall(k): mismatches.append((db,k,"hash"))
            fl=list(s.hgetall(k).keys())
            se=s.execute_command("HPEXPIRETIME",k,"FIELDS",len(fl),*fl)
            de=d.execute_command("HPEXPIRETIME",k,"FIELDS",len(fl),*fl)
            for f,a,b in zip(fl,se,de):
                if a==-1 and b==-1: continue
                if a==-1 or b==-1 or abs(int(a)-int(b))>5000:
                    mismatches.append((db,k,"hfieldexp",f,a,b))
        elif st=="stream":
            if s.xrange(k,"-","+")!=d.xrange(k,"-","+") or s.xlen(k)!=d.xlen(k):
                mismatches.append((db,k,"stream-entries"))
            sg={g['name']:g for g in s.xinfo_groups(k)}
            dg={g['name']:g for g in d.xinfo_groups(k)}
            if set(sg)!=set(dg):
                mismatches.append((db,k,"groups",set(sg),set(dg))); continue
            for gname in sg:
                if sg[gname]['last-delivered-id']!=dg[gname]['last-delivered-id']:
                    mismatches.append((db,k,"g-lastid",gname,sg[gname]['last-delivered-id'],dg[gname]['last-delivered-id']))
                if int(sg[gname]['pending'])!=int(dg[gname]['pending']):
                    mismatches.append((db,k,"g-pending",gname,sg[gname]['pending'],dg[gname]['pending']))
                sp=s.xpending_range(k,gname,min="-",max="+",count=1000000)
                dp=d.xpending_range(k,gname,min="-",max="+",count=1000000)
                sp2=sorted((p['message_id'],p['consumer']) for p in sp)
                dp2=sorted((p['message_id'],p['consumer']) for p in dp)
                if sp2!=dp2:
                    mismatches.append((db,k,"pel",gname,sp2[:3],dp2[:3]))
        # TTL tolerance
        sp=s.pttl(k); dp=d.pttl(k)
        if (sp<0)!=(dp<0):
            mismatches.append((db,k,"ttl-sign",sp,dp))
        elif sp>=0 and abs(sp-dp)>5000:
            mismatches.append((db,k,"ttl",sp,dp))
    print(f"db{db} checked {len(sk)} keys")

print("MISMATCHES:", len(mismatches))
for m in mismatches[:30]: print(" ", m)
EOF
